import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double eps = 1e-15;
        int a = sc.nextInt();
        int b = sc.nextInt();
        int n = sc.nextInt();
        double ratio = (double) a / b;

        int numerator = a;
        int denominator = b;
        double best_diff = 1e9;

        for (int i = 1; i <= n; i++) {
            double val = ((double) a * i) / b;
            double floor_val = Math.floor(val);
            double ceil_val = Math.ceil(val);
            double rat_floor = floor_val / i;
            double rat_ceil = ceil_val / i;
            double diff_floor = Math.abs(rat_floor - ratio);
            double diff_ceil = Math.abs(rat_ceil - ratio);

            if (diff_ceil == diff_floor) {
                if (diff_ceil < best_diff - eps) {
                    numerator = (int) floor_val;
                    denominator = i;
                    best_diff = diff_ceil;
                }
            } else if (diff_ceil < diff_floor) {
                if (diff_ceil < best_diff - eps) {
                    numerator = (int) ceil_val;
                    denominator = i;
                    best_diff = diff_ceil;
                }
            } else {
                if (diff_floor < best_diff - eps) {
                    numerator = (int) floor_val;
                    denominator = i;
                    best_diff = diff_floor;
                }
            }
        }
        System.out.println(numerator + "/" + denominator);
        sc.close();
    }
}
